<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Profile - DormSync</title><style>*{box-sizing:border-box}body{background:#f7f9fc;color:#172033;font-family:Arial,sans-serif;margin:0}main{max-width:620px;margin:auto;padding:40px 24px}.topbar{background:#fff;border-bottom:1px solid #e7ebf2;padding:18px 6%}.topbar a{color:#2563eb}.panel{background:#fff;border:1px solid #e7ebf2;border-radius:8px;padding:24px}label{display:block;font-weight:600;font-size:13px;margin:14px 0 6px}input,button{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:6px;font:inherit}button{margin-top:18px;background:#2563eb;color:#fff;border-color:#2563eb;font-weight:600}.message{padding:10px;margin-bottom:12px;background:#dcfce7;color:#166534}.error{color:#991b1b}</style></head><body><header class="topbar"><a href="/admin/dashboard">&larr; Back to dashboard</a></header><main><section class="panel"><h1>Admin profile</h1><?php if($success):?><div class="message"><?=htmlspecialchars($success)?></div><?php endif;?><?php foreach($errors as $fieldErrors):foreach((array)$fieldErrors as $error):?><p class="error"><?=htmlspecialchars($error)?></p><?php endforeach;endforeach;?><form method="post" action="/admin/profile-update"><label>Full name</label><input name="full_name" value="<?=htmlspecialchars($admin['full_name'] ?? '')?>" required><label>Phone</label><input name="phone" value="<?=htmlspecialchars($admin['phone'] ?? '')?>"><label>New password (optional)</label><input name="password" type="password" minlength="6"><button type="submit">Save profile</button></form><p>Email: <?=htmlspecialchars($admin['email'] ?? '')?></p></section></main></body></html>
